command:
Write-Output ("=== launch with full access " + (Get-Date -Format HH:mm:ss) + " ===")
$p = Start-Process -FilePath "D:\SolidWorks 2026\SOLIDWORKS\SLDWORKS.exe" -PassThru
Write-Output ("pid=" + $p.Id)
for ($i=0; $i -lt 24; $i++) {
  Start-Sleep -Seconds 5
  if ($p.HasExited) { Write-Output ("[" + (Get-Date -Format HH:mm:ss) + "] EXITED code=" + $p.ExitCode); break }
  $proc = Get-Process -Id $p.Id -ErrorAction SilentlyContinue
  if ($proc) { Write-Output ("[" + (Get-Date -Format HH:mm:ss) + "] alive mem=" + [math]::Round($proc.WorkingSet64/1MB,0) + "MB title='" + $proc.MainWindowTitle + "'") }
}
Write-Output "--- procs ---"
Get-Process | Where-Object { $_.ProcessName -match 'SLDWORKS' } | Select-Object ProcessName,Id,MainWindowTitle | Format-Table -AutoSize | Out-String -Width 200

$ErrorActionPreference='Continue'
try {
  $sw = New-Object -ComObject SldWorks.Application
  Write-Output ("created, type=" + $sw.GetType().FullName)
  Write-Output ("Caption=" + ($sw.Caption -join ''))
  Write-Output ("Visible=" + $sw.Visible)
  Write-Output ("GetDocumentCount=" + $sw.GetDocumentCount())
  Write-Output "--- common props ---"
  foreach ($p in @('RevisionNumber','VersionMajor','VersionMinor','IsBackground')) {
    try { Write-Output ("$p = " + $sw.$p) } catch { Write-Output ("$p ERR: " + $_.Exception.Message.Substring(0,60)) }
  }
  Write-Output "--- templates ---"
  Write-Output ("UserTemplatePath(part)=" + $sw.GetUserPreferenceStringValue(8))
  Write-Output ("DefaultTemplate(part)=" + $sw.GetUserPreferenceStringValue(8))
} catch { Write-Output ("FAIL: " + $_.Exception.Message) }

$ErrorActionPreference='Continue'
$cls = "Registry::HKEY_CLASSES_ROOT\CLSID\{666AAEE2-7A21-40FC-B768-2078840A88C3}"
Write-Output "=== InprocHandler32 ==="
Get-ItemProperty "$cls\InprocHandler32" -ErrorAction SilentlyContinue | Format-List | Out-String -Width 300
Write-Output "=== TypeLib value ==="
$tl = Get-ItemProperty "$cls\TypeLib" -ErrorAction SilentlyContinue
if ($tl) { Write-Output ("TypeLib GUID = " + $tl.'(default)') }
Write-Output "=== Version ==="
Get-ItemProperty "$cls" -ErrorAction SilentlyContinue | Select-Object '(default)','AppID','LocalizedString' | Format-List | Out-String -Width 300
Write-Output "=== TypeLib registration check ==="
foreach ($v in @('Registry::HKEY_CLASSES_ROOT\TypeLib','Registry::HKEY_CLASSES_ROOT\WOW6432Node\TypeLib')) {
  Write-Output ("under " + $v)
  $node = "$v\{83A33D31-27C5-11CE-BFD4-00400513BB57}"
  if (Test-Path $node) { Get-ChildItem $node -Recurse -ErrorAction SilentlyContinue | Select-Object -First 10 Name | Format-Table -AutoSize | Out-String -Width 250 } else { Write-Output "  (not present)" }
}
Write-Output "=== reflection invoke test ==="
try {
  $t = [System.Type]::GetTypeFromProgID("SldWorks.Application")
  $sw = [System.Activator]::CreateInstance($t)
  Write-Output ("instance type: " + $sw.GetType().FullName)
  $r = $t.InvokeMember("RevisionNumber", [System.Reflection.BindingFlags]::GetProperty, $null, $sw, $null)
  Write-Output ("RevisionNumber via reflection = " + $r)
} catch { Write-Output ("REFLECT_FAIL: " + $_.Exception.Message) }

$ErrorActionPreference='Continue'
Write-Output "=== typelib win64 path (64-bit) ==="
$tlp = "Registry::HKEY_CLASSES_ROOT\TypeLib\{83A33D31-27C5-11CE-BFD4-00400513BB57}\22.0\0\win64"
Get-ItemProperty $tlp -ErrorAction SilentlyContinue | Format-List | Out-String -Width 300
Write-Output "=== does the typelib file exist? ==="
$v = (Get-ItemProperty $tlp -ErrorAction SilentlyContinue).'(default)'
Write-Output ("path = " + $v)
if ($v) { Write-Output ("exists = " + (Test-Path $v)) }
Write-Output "=== control test: another COM object (Shell.Application) ==="
try {
  $sh = New-Object -ComObject Shell.Application
  Write-Output ("Shell OK, Windows count=" + $sh.Windows().Count)
} catch { Write-Output ("Shell FAIL: " + $_.Exception.Message) }
Write-Output "=== control test: Excel-like Scripting.Dictionary ==="
try {
  $d = New-Object -ComObject Scripting.Dictionary
  Write-Output ("Dict OK Count=" + $d.Count)
} catch { Write-Output ("Dict FAIL: " + $_.Exception.Message) }
Write-Output "=== control: SldWorks type members count via IDispatch ==="
try {
  $t = [System.Type]::GetTypeFromProgID("SldWorks.Application")
  Write-Output ("type name=" + $t.FullName + " isCOM=" + $t.IsCOMObject)
} catch { Write-Output ("type err: " + $_.Exception.Message) }

$ErrorActionPreference='Continue'
Write-Output "=== check running SW readiness strictly ==="
Get-Process -Name SLDWORKS -ErrorAction SilentlyContinue | Select-Object Id,MainWindowTitle,StartTime | Format-Table -AutoSize | Out-String -Width 250
Write-Output "=== wait longer then retry COM (60s) ==="
for ($i=1; $i -le 6; $i++) {
  Start-Sleep -Seconds 10
  try {
    $sw = New-Object -ComObject SldWorks.Application
    $r =  $sw.RevisionNumber
    Write-Output ("attempt " + $i + ": OK rev=" + $r)
    Write-Output ("Visible=" + $sw.Visible + " docs=" + $sw.GetDocumentCount())
    break
  } catch { Write-Output ("attempt " + $i + ": " + $_.Exception.Message.Substring(0,70)) }
}

$exe="D:\SolidWorks 2026\SOLIDWORKS\SLDWORKS.exe"
$p = Start-Process -FilePath $exe -WorkingDirectory (Split-Path $exe) -PassThru
"started pid=$($p.Id)"
for ($i=0; $i -lt 40; $i++) {
  Start-Sleep 3
  if ($p.HasExited) { "EXITED at $($i*3)s codes=$($p.ExitCode)"; break }
}
if (-not $p.HasExited) { "STILL RUNNING at 120s pid=$($p.Id) mem=$([math]::Round((Get-Process -Id $p.Id).WorkingSet64/1MB))MB title=$((Get-Process -Id $p.Id).MainWindowTitle)" }

$L="__HOME__\Desktop\dsh\_tools\pylibs"
$env:PYTHONPATH="$L;$L\win32;$L\win32\lib"
$env:PATH="$L\pywin32_system32;$env:PATH"
$env:PYTHONIOENCODING="utf-8"
$PY="__HOME__\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
$R="__HOME__\.dsh\.agent-presets\engineering"
# 关掉挡在前面的 SOLIDWORKS CAM 消息窗口
Add-Type @"
using System;using System.Runtime.InteropServices;
public class W { [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern IntPtr FindWindow(string c,string n);
[DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l); }
"@
$h=[W]::FindWindow($null,"SOLIDWORKS CAM 消息窗口")
if ($h -ne [IntPtr]::Zero) { [W]::PostMessage($h,0x0010,[IntPtr]::Zero,[IntPtr]::Zero) | Out-Null; "CAM window closed" } else { "no CAM window" }
Start-Sleep 2
& $PY "$R\tools\sw_bridge.py" run "__HOME__\Desktop\dsh\_tools\probe_views.py" 2>&1 | ConvertFrom-Json | ForEach-Object { $_.script_stdout; "OK=$($_.ok) ERR=$($_.error)" }

$cands = @("D:\dsh guanfnag\resources\runtime\cli\bin\dsh.cmd","D:\dsh guanfnag\resources\runtime\cli\bin\dsh.exe")
foreach ($c in $cands) { if (Test-Path $c) { "FOUND: $c" } }
Write-Host "=== npm registry check ==="
try {
  $r = Invoke-RestMethod -Uri "https://registry.npmjs.org/dsh-auto-approval-plugin" -TimeoutSec 25
  "name: " + $r.name
  "latest: " + $r.'dist-tags'.latest
  "desc: " + $r.description
  "modified: " + $r.time.modified
} catch { "npm query failed: " + $_.Exception.Message }

$pkgs = @("dsh-auto-approval-plugin","@dnalec/dsh-auto-approve","dsh-auto-reviewer","@mrweicodes/dsh-permgate","@dsh-plugin/dsh-approve-for-me")
foreach ($p in $pkgs) {
  $u = "https://registry.npmjs.org/" + ($p -replace "/","%2F")
  try {
    $r = Invoke-RestMethod -Uri $u -TimeoutSec 25
    $latest = $r.'dist-tags'.latest
    $v = $r.versions.$latest
    "== $p  latest=$latest  modified=$($r.time.modified)"
    "   desc: $($v.description)"
    $req = $v.dependencies, $v.peerDependencies, $v.dsh
    "   dsh field: " + ($v.dsh | ConvertTo-Json -Compress -Depth 4)
    "   peerDeps: " + ($v.peerDependencies | ConvertTo-Json -Compress -Depth 4)
    "   deps: " + ($v.dependencies | ConvertTo-Json -Compress -Depth 4)
  } catch { "== $p  FAILED: $($_.Exception.Message)" }
}

try {
  $r = Invoke-RestMethod -Uri "http://127.0.0.1:58073/permgate/reload" -Method Post -TimeoutSec 20
  $r | ConvertTo-Json -Depth 4 -Compress
} catch {
  "POST failed: " + $_.Exception.Message
  try { (Invoke-RestMethod -Uri "http://127.0.0.1:58073/permgate/reload" -TimeoutSec 15) | ConvertTo-Json -Depth 4 -Compress } catch { "GET also failed: " + $_.Exception.Message }
}

$p = Start-Process "D:\SolidWorks 2026\SOLIDWORKS\SLDWORKS.exe" -PassThru
"pid=$($p.Id)"
Start-Sleep -Seconds 90
$proc = Get-Process -Id $p.Id -ErrorAction SilentlyContinue
if ($proc) {
  "ALIVE ws=$([math]::Round($proc.WorkingSet64/1MB))MB"
  Get-Process | Where-Object { $_.Path -match "SolidWorks" } | Select-Object Id,ProcessName | Format-Table
} else { "CRTASHED again" }

Write-Output '=== WER 崩溃报告 ==='
Get-ChildItem "$env:LOCALAPPDATA\Microsoft\Windows\WER\ReportArchive","$env:LOCALAPPDATA\Microsoft\Windows\WER\ReportQueue","$env:PROGRAMDATA\Microsoft\Windows\WER\ReportArchive" -Directory -ErrorAction SilentlyContinue |
  Where-Object { $_.Name -match 'SLDWORKS|AppCrash' } | Sort-Object LastWriteTime -Descending | Select-Object -First 3 FullName, LastWriteTime | Format-Table -AutoSize -Wrap
$r = Get-ChildItem "$env:LOCALAPPDATA\Microsoft\Windows\WER" -Recurse -Filter 'Report.wer' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($r) { Write-Output ("--- " + $r.FullName); Get-Content $r.FullName -TotalCount 40 }
Write-Output ''
Write-Output '=== 启动 SW（full access）==='
Start-Process -FilePath 'D:\SolidWorks 2026\SOLIDWORKS\SLDWORKS.exe'
$deadline=(Get-Date).AddSeconds(200); $ready=$false
while((Get-Date) -lt $deadline){
  $p = Get-Process SLDWORKS -ErrorAction SilentlyContinue
  if($p){
    $main = $p | Where-Object { $_.MainWindowHandle -ne 0 }
    if($main){ Write-Output ("READY pid=" + $main.Id + " title=" + $main.MainWindowTitle); $ready=$true; break }
    Write-Output ("启动中... pids=" + (($p | ForEach-Object { $_.Id }) -join ','))
  } else { Write-Output '等待进程...' }
  Start-Sleep -Seconds 10
}
if(-not $ready){ Write-Output '超时或崩溃' }

Start-Process -FilePath "explorer.exe" -ArgumentList '"D:\SolidWorks 2026\SOLIDWORKS\SLDWORKS.exe"'
Write-Output "launched"
$p = "__HOME__\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe"
for ($i=1; $i -le 12; $i++) {
  Start-Sleep -Seconds 15
  $n = (Get-Process -Name "SLDWORKS" -ErrorAction SilentlyContinue | Measure-Object).Count
  Write-Output ("t=" + ($i*15) + "s SLDWORKS_count=" + $n)
  if ($n -gt 0) {
    $r = & $p -c @'
import sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
try:
    import win32com.client as w
    o = w.Dispatch("SldWorks.Application")
    print("COM_OK rev=" + str(o.RevisionNumber()))
except Exception as e:
    print("COM_FAIL " + repr(e)[:200])
'@
    Write-Output $r
    if ($r -match "COM_OK") { Write-Output "SUCCESS"; break }
  }
}
Write-Output "END"
